formulas.expression:
VALUE(
    LEFT(
        RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("BIOS battery:", {!OutputFormatFetched}) - LEN("BIOS battery:")), 
        FIND("</b>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("BIOS battery:", {!OutputFormatFetched}) - LEN("BIOS battery:"))) - 1
    )
)

VALUE(
  LEFT(
    RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("Detector Contrast Reading:", {!OutputFormatFetched}) - LEN("Detector Contrast Reading:")),
    FIND("<br>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("Detector Contrast Reading:", {!OutputFormatFetched}) - LEN("Detector Contrast Reading:"))) - 1
  )
)

VALUE(
  LEFT(
    RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("Detector Resolution Reading:", {!OutputFormatFetched}) - LEN("Detector Resolution Reading:")),
    FIND("<br>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("Detector Resolution Reading:", {!OutputFormatFetched}) - LEN("Detector Resolution Reading:"))) - 1
  )
)
